referenceSolutions.javascript:
function chainTurntablePeakTicket(head, k) {
  const a=head; let out=[];
  let previous=null,node=a;while(node){const next=node.next;node.next=previous;previous=node;node=next;}for(node=previous;node;node=node.next)out.push(node.val);
  let answer=out.length?out[0]:0;for(const x of out)if(x>answer)answer=x;return answer;
}

